import{f as e,h as t,j as n,n as r}from"./chunks/shared.rYHlazZf.js";var i=JSON.parse(`{"title":"准备协作与团队访问","description":"","frontmatter":{"title":"准备协作与团队访问","docId":"user.cloud.collaboration","translationKey":"user.cloud.collaboration","locale":"zh","audience":"user","featureStatus":"experimental","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"05f448dda78b05027b84b2c03f08a15eb515aee05af79397a1596d7e40ec5d40","translationRevision":"d0c0e6ce583468a8f45ef61e17b6e9aca9cb6a974b767493b875e2c8af657ee4","order":30},"headers":[],"relativePath":"zh/user/cloud/collaboration.md","filePath":"zh/user/cloud/collaboration.md","lastUpdated":1795727787000}`),a={name:`zh/user/cloud/collaboration.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="prepare-collaboration-and-team-access" tabindex="-1">准备协作与团队访问 <a class="header-anchor" href="#prepare-collaboration-and-team-access" aria-label="Permalink to “准备协作与团队访问”">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">目标与前提 <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to “目标与前提”">​</a></h2><p>在保留所有者控制权的前提下，为另一位操作员分配明确的角色。远程访问由可安装的 <strong>Remote Control</strong> 插件提供，而不是设置中的选项卡：需要 <a href="./account.html">Cloud 登录</a>、匹配的后端，并为此主机安装该插件。请从只读访问和非生产环境开始。</p><h2 id="configure-remote-access" tabindex="-1">配置远程访问 <a class="header-anchor" href="#configure-remote-access" aria-label="Permalink to “配置远程访问”">​</a></h2><ol><li>安装并启用 <code>tiktools.remote-control</code>，然后打开其 <strong>Remote control</strong> 页面。</li><li>创建团队，将<strong>此电脑</strong>注册为主机并使用易于识别的设备名称；启动中继链路，等待状态达到 <code>ready</code>。</li><li>创建邀请，并通过可信渠道交付一次性令牌。邀请不等于已批准的活动会话。</li><li>检查待处理请求和所请求的角色。只批准预期的操作员；在主机链路确认之前，授权保持 <code>pendingHost</code>。</li><li>定期检查授权和设备。不再需要时撤销授权。</li></ol><p>委派编辑定义、以所有者身份采用定义以及批准委派执行是不同的决定。请在具体评审中阅读保存的源、引用的操作和权限。仅有定义预览并不授权任何效果。</p><h2 id="prepare-a-controller-device" tabindex="-1">准备控制端设备 <a class="header-anchor" href="#prepare-a-controller-device" aria-label="Permalink to “准备控制端设备”">​</a></h2><p>在控制端设备上使用其自己的账户登录，将其注册为控制端并兑换邀请令牌。所有者随后会看到待处理请求。昵称查询需要单独部署的后端端点，当前服务可能不可用。不要因查询失败就认为对方没有账户，也不要用任意 ID 替代选择。</p><h2 id="expected-result-and-status" tabindex="-1">预期结果与状态 <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to “预期结果与状态”">​</a></h2><p>双账户流程（团队、主机链路、邀请、批准、读取命令、撤销）已在本地后端验证。设置中的 Collaboration/Teams 选项卡已移除；本版本中原生 collaboration 服务没有 Web 界面。生产环境的中继/NAT 行为、昵称查询和双机 LIVE 运行未在此确认。链路就绪本身并不能证明针对你预期操作的权限已端到端生效。</p><h2 id="recovery" tabindex="-1">恢复 <a class="header-anchor" href="#recovery" aria-label="Permalink to “恢复”">​</a></h2><p>对于过期的授权，请撤销访问并在主机链路刷新后重新检查。对于未确认的命令，请在重试前检查记录的结果。结束会话时停止中继链路或撤销访问。请勿将邀请令牌和凭据写入公开的<a href="./../preferences/troubleshooting.html">诊断报告</a>。</p><h2 id="operational-details" tabindex="-1">操作细节 <a class="header-anchor" href="#operational-details" aria-label="Permalink to “操作细节”">​</a></h2><p>每条远程命令都要经过主机的能力网关（<code>remote.command.dispatch</code>、<code>remote.pair.list</code>、<code>remote.grant.list</code>、<code>remote.grant.revoke</code>、<code>remote.controller.ticket</code>）；插件不会收到 Control API 或完整的 bearer 令牌。活动传输或团队身份本身并不授予原生访问权限。Observer 偏向读取；moderator 增加部分操作控制，automationEditor 增加部分编辑能力，custom 需要明确且经过审查的策略。它们都不授予无限制的脚本或效果。当前边界请参阅<a href="./../../developer/collaboration.html#operational-details">角色与确认契约</a>和<a href="./../../developer/transports.html">传输</a>。</p>`,14)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};